BNGParser::BNGParser(TokenStream *input) : BNGParser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

BNGParser::BNGParser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  BNGParser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *bngparserParserStaticData->atn, bngparserParserStaticData->decisionToDFA, bngparserParserStaticData->sharedContextCache, options);
}

BNGParser::~BNGParser() {
  delete _interpreter;
}

const atn::ATN& BNGParser::getATN() const {
  return *bngparserParserStaticData->atn;
}

std::string BNGParser::getGrammarFileName() const {
  return "BNGParser.g4";
}

const std::vector<std::string>& BNGParser::getRuleNames() const {
  return bngparserParserStaticData->ruleNames;
}

const dfa::Vocabulary& BNGParser::getVocabulary() const {
  return bngparserParserStaticData->vocabulary;
}

antlr4::atn::SerializedATNView BNGParser::getSerializedATN() const {
  return bngparserParserStaticData->serializedATN;
}


